style.css:
/* After Hours — SoundCloud */

/* change these values to adjust the look */
:root {
  --my-dim: rgba(0, 0, 0, 0.30);
  --my-text: #ffffff;
}

/* background photo + dimming */
html,
body {
  background-color: #111 !important;
  background-image:
    linear-gradient(
      var(--my-dim),
      var(--my-dim)
    ),
    url("https://i.postimg.cc/nVsprtyD/ye-ye-ye.jpg") !important;
  background-position: center center !important;
  background-size: cover !important;
  background-repeat: no-repeat !important;
  background-attachment: fixed !important;
  color: var(--my-text) !important;
}

/* white text */
body {
  color: #ffffff !important;
}

/* white links */
a {
  color: #ffffff !important;
}
